import csv, io, urllib.request, collections
for name, key in [('EVIDENCE','REDACTED'),('CALENDAR','REDACTED')]:
    try:
        with urllib.request.urlopen(f'https://docs.google.com/spreadsheets/d/{key}/export?format=csv', timeout=15) as response:
            kind=response.headers.get_content_type()
            print(name, response.status, kind)
            if kind != 'text/csv':
                continue
            reader=csv.DictReader(io.StringIO(response.read().decode('utf-8-sig')))
            rows=list(reader)
        print('Headers:', reader.fieldnames, 'Rows:',len(rows))
        for field in reader.fieldnames or []:
            vals=[(row.get(field) or '').strip() for row in rows]
            counts=collections.Counter(v for v in vals if v)
            if field.endswith('_id') or field in ('system_id','system_ids'):
                print(field,'distinct',len(counts),'blank',vals.count(''),'duplicates',sum(v-1 for v in counts.values()))
                if field == 'system_id':
                    expected={f'AI-{i:03}' for i in range(1,9)}
                    print('Matched:',sorted(expected & counts.keys()),'Unmatched:',sorted(counts.keys()-expected))
            if any(word in field for word in ('date','version','updated','_at','due')):
                print(field,sorted(counts),'blank',vals.count(''))
    except Exception as error:
        print(name,type(error).__name__,str(error))
